void BusinessAccessInvite::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Post("/businesses/{business_id}/requests/assets/access", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdrequestsassetsaccessPostRequest(req, res, auth);
    });
    svr.Delete("/businesses/{business_id}/invites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdinvitesDeleteRequest(req, res, auth);
    });
    svr.Post("/businesses/{business_id}/invites/assets/access", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdinvitesassetsaccessPostRequest(req, res, auth);
    });
    svr.Post("/businesses/{business_id}/invites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdinvitesPostRequest(req, res, auth);
    });
    svr.Get("/businesses/{business_id}/invites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdinvitesGetRequest(req, res, auth);
    });
    svr.Patch("/businesses/invites", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesinvitesPatchRequest(req, res, auth);
    });
}

